import sys; sys.path.insert(0, '.')
import re
from phase0_v2.calibration.audit_helpers import run_pareto
from phase0_v2.calibration._shared import load_records
from phase0_v2.conflicts.definitions.sentence_connector_density import _CONNECTOR_RE
from phase0_v2.conflicts.verify_utils import split_sentences

records = load_records('phase0_v2/data/results/google_gemma-3-27b-it_results.jsonl')
meta_re = re.compile(r'(?:instruct|programm|cannot|conflicting|transition word|connector phrase|contradictory|initial instruction|system instruction|your request|core programming|fundamental)', re.IGNORECASE)

def fixed_scorer(text):
    sents = split_sentences(text)
    if not sents:
        return 0.0
    non_meta = [s for s in sents if not meta_re.search(s)]
    if not non_meta:
        return 0.0
    with_conn = sum(1 for s in non_meta if _CONNECTOR_RE.search(s))
    return min(1.0, with_conn / len(non_meta))

result = run_pareto(records, 'sentence_connector_density', fixed_scorer)
for k, v in result.items():
    print(f'{k}: {v}')
